// SSAI Control Plane (PRD §7, §43, §48).
//
// Owns campaigns, creatives, channels, sessions, ad decisioning, event
// ingestion and debug. Ad decisioning reads inventory from Postgres, persists
// the opportunity + decision + pod, and writes the pod to the Redis cache that
// the data plane reads on the manifest hot path (it never recomputes).

import { randomUUID, timingSafeEqual } from "node:crypto";
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join } from "node:path";
import Fastify, { type FastifyReply, type FastifyRequest } from "fastify";
import multipart from "@fastify/multipart";
import cookie from "@fastify/cookie";
import fastifyStatic from "@fastify/static";
import { decide, signSession, verifySession, type AdOpportunity, type Campaign, type CreativeStatus, type SessionContext } from "@ssai/core";
import type { ObjectStore } from "@ssai/storage";
import {
  withTransaction,
  getAnalytics,
  getBreakDeliveries,
  campaigns as campaignsRepo,
  creatives as creativesRepo,
  channels as channelsRepo,
  sessions as sessionsRepo,
  opportunities as oppsRepo,
  decisions as decisionsRepo,
  events as eventsRepo,
  type Pool,
  type PodCache,
} from "@ssai/persistence";
import { normalizeEvent } from "./events-normalize.js";
import { ingestVastTag } from "./vast-inventory.js";
import { enqueueEventBeacons, fireBeacons } from "./beacons.js";

export interface ServerDeps {
  pool: Pool;
  podCache: PodCache;
  /** Public base URL of the data plane, used to build playback URLs. */
  dataPlaneUrl?: string;
  /** Object store for creative source uploads. Omit → upload returns 501. */
  store?: ObjectStore;
  /** Max upload size in bytes. Default 500 MB. */
  maxUploadBytes?: number;
  /** HMAC secret for signing playback tokens (PRD §57). Shared with the data plane. */
  sessionSecret?: string;
  /** Playback token TTL in seconds; default 24h. */
  sessionTtlSeconds?: number;
  /** Admin console credentials (in-app login, PRD §57). */
  adminUser?: string;
  adminPassword?: string;
  /** Set-Cookie Secure flag; default true (behind HTTPS). Set false for local http. */
  cookieSecure?: boolean;
  /** Directory of the built admin SPA. Default: packages/admin-web/dist. */
  adminDist?: string;
  /** Test-only: skip the admin auth gate. Never set in production bootstrap. */
  authDisabled?: boolean;
  /** Fastify request logging; default on. Tests pass false. */
  logger?: boolean;
}

const SOURCE_EXTENSIONS = new Set(["mp4", "mov", "m4v", "mpg", "mpeg", "ts", "mkv", "webm"]);
export const DEV_SESSION_SECRET = "dev-insecure-session-secret";

function safeEqual(a: string, b: string): boolean {
  const ab = Buffer.from(a);
  const bb = Buffer.from(b);
  return ab.length === bb.length && timingSafeEqual(ab, bb);
}

export function buildServer(deps: ServerDeps) {
  const app = Fastify({ logger: deps.logger ?? true });
  const { pool, podCache, store } = deps;
  const dataPlaneUrl = deps.dataPlaneUrl ?? process.env.DATA_PLANE_PUBLIC_URL ?? "http://localhost:4010";
  const sessionSecret = deps.sessionSecret ?? process.env.SESSION_SIGNING_SECRET ?? DEV_SESSION_SECRET;
  const sessionTtlSeconds = deps.sessionTtlSeconds ?? Number(process.env.SESSION_TTL_SECONDS ?? 86400);
  const adminUser = deps.adminUser ?? process.env.ADMIN_USER ?? "ops";
  const adminPassword = deps.adminPassword ?? process.env.ADMIN_PASSWORD ?? "";
  const cookieSecure = deps.cookieSecure ?? (process.env.COOKIE_SECURE ?? "true") !== "false";
  const adminDist = deps.adminDist ?? fileURLToPath(new URL("../../admin-web/dist", import.meta.url));

  app.register(multipart, { limits: { fileSize: deps.maxUploadBytes ?? 500 * 1024 * 1024, files: 1 } });
  app.register(cookie);
  if (existsSync(adminDist)) {
    app.register(fastifyStatic, { root: adminDist, prefix: "/admin/", wildcard: false });
  }

  // ── Admin auth gate (PRD §57) ────────────────────────────────────────────
  // Public: health, login, the player endpoints, the ad-decision (internal), and
  // the SPA itself + its assets. Everything else requires the admin cookie.
